import { Check, ArrowSquareOut, CircleNotch, Image, Info, Person, Warning } from "@phosphor-icons/react";
import { useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import "./AutoFitWorkspace.css";
import { WorkspaceHeader, WorkspaceHeaderContext } from "./WorkspaceHeader.jsx";
import { BodyReferenceWorkspace } from "./BodyReference.jsx";
import { FitViewport } from "./FitViewport.jsx";
import { ScaleRange } from "./ScaleRange.jsx";
import { NumericInput } from "./NumericInput.jsx";
import { SelectField } from "./SelectField.jsx";
import { DataTable } from "./DataTable.jsx";
import { PHOTO_SCREENING_VERSION, photoTargetKey } from "./body-reference-draft.js";
import { hasUsableReferenceMeasurements } from "./body-reference-results.js";
import { playerNameFromLabel } from "../server/player-label.mjs";
import { SHOES } from "./shoes.js";
import { GameRunNote } from "./GameRunNote.jsx";
import { requestJson } from "./api.js";
import { BODY_PARTS, BODY_REGIONS, BODY_FIT_MIN, BODY_FIT_MAX, mergedBodyFitValue, expandBodyFitValue } from "../server/appearance-fields.mjs";
import { LIMB_FIELDS } from "./AppearanceEditor.jsx";

const STEPS = ["身型参考", "身型画像", "调整预览", "写入与验收"];
const SEASONS = Array.from({ length: 81 }, (_, index) => { const year = 2026 - index; const value = `${year}-${String((year + 1) % 100).padStart(2, "0")}`; return { value, label: value }; });
const TEAMS = [
  "Atlanta Hawks", "Boston Celtics", "Brooklyn Nets", "Charlotte Hornets", "Chicago Bulls",
  "Cleveland Cavaliers", "Dallas Mavericks", "Denver Nuggets", "Detroit Pistons", "Golden State Warriors",
  "Houston Rockets", "Indiana Pacers", "LA Clippers", "Los Angeles Lakers", "Memphis Grizzlies",
  "Miami Heat", "Milwaukee Bucks", "Minnesota Timberwolves", "New Orleans Pelicans", "New York Knicks",
  "Oklahoma City Thunder", "Orlando Magic", "Philadelphia 76ers", "Phoenix Suns", "Portland Trail Blazers",
  "Sacramento Kings", "San Antonio Spurs", "Toronto Raptors", "Utah Jazz", "Washington Wizards",
].map((value) => ({ value, label: value }));
const BUILDS = [{ value: "lean", label: "精瘦" }, { value: "balanced", label: "匀称" }, { value: "built", label: "壮硕" }, { value: "heavy", label: "厚重" }];
const EMPHASIS = [{ value: "auto", label: "跟随整体" }, { value: "strong", label: "偏粗壮" }, { value: "slim", label: "偏纤细" }];
const post = (url, data, method = "POST") => requestJson(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(data) });
const sameBody = (left, right) => Object.keys(left || {}).every((key) => Number(left[key]) === Number(right?.[key]));
const numeric = (value) => value == null ? "—" : Number(value).toFixed(2);
const LIMB_GROUPS = [["upperarm", "上臂"], ["forearm", "前臂"], ["thigh", "大腿"], ["calf", "小腿"]];
const LIMB_IDENTITY_SEG = { scale: 1, bulge: 0, taper: 0, inner: 0, triceps: 0, tricepsLine: 0 };
const WRITE_COLUMNS = [{ key: "label", title: "部位" }, { key: "before", title: "写入前", render: (row) => numeric(row.before) }, { key: "target", title: "目标", render: (row) => numeric(row.target) }];
// v0.2 照片比例对照（2026-10-15）：照片融合值 vs 游戏基线（服务端直读包网格）。
const PROPORTION_LABELS = { visibleHeadToShoulderRatio: "头肩比", headHeightToTorsoProxy: "头高/躯干", shoulderToHipProxy: "肩胯比", visibleUpperArmWidthProfile: "上臂宽/肩跨" };
const PROPORTION_COLUMNS = [{ key: "label", title: "特征" }, { key: "photo", title: "照片" }, { key: "game", title: "游戏" }, { key: "gap", title: "差值" }, { key: "action", title: "处置" }];

// 统一任务只编排既有参考分析、求解、视口覆盖与 appearance 事务；不复制算法。
export function AutoFitWorkspace({ playerId, players, modsRoot, theme, rulerUnit, showGrid, showAxes, onCompareApi, onBodyChanged }) {
  const headerScope = useContext(WorkspaceHeaderContext);
  const storageKey = `fit-studio.autofit.${playerId}`;
  const [stored] = useState(() => { try { return JSON.parse(localStorage.getItem(storageKey) || "null") || {}; } catch { return {}; } });
  const [team, setTeam] = useState(stored.team || "");
  const [season, setSeason] = useState(stored.season || "");
  const [step, setStep] = useState(stored.step || 0);
  // B-2（UI 方案 2026-10-31）：窄屏步骤条横滚时当前步自动居中可见（方案验收「下一步后视口定位到新当前步」）。
  const stepsNavRef = useRef(null);
  useEffect(() => {
    stepsNavRef.current?.querySelector(".active")?.scrollIntoView({ block: "nearest", inline: "center", behavior: "smooth" });
  }, [step]);
  const [profile, setProfile] = useState(stored.profile || { heightCm: "", weightKg: "", buildType: "balanced", traits: [] });
  const [plan, setPlan] = useState(stored.plan || null);
  const [writeResult, setWriteResult] = useState(stored.writeResult || null);
  const [accepted, setAccepted] = useState(stored.accepted || false);
  const [reference, setReference] = useState(null);
  const referenceAnalysisRef = useRef(null);
  const [status, setStatus] = useState(null);
  const [comparison, setComparison] = useState(null);
  const [appearance, setAppearance] = useState(null);
  const [research, setResearch] = useState(null);
  const [career, setCareer] = useState(null);
  const [importedImages, setImportedImages] = useState(null);
  const searchRequestRef = useRef(0);
  const searchTargetRef = useRef("");
  // 用户是否亲手改过赛季/球队：改过之后任何自动回填（档案、生涯纠正）都不许再碰。
  const userSeasonRef = useRef(false);
  const userTeamRef = useRef(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [storageError, setStorageError] = useState("");
  const [checking, setChecking] = useState(false);
  const [region, setRegion] = useState("arms");
  const [view, setView] = useState("front");
  const [compare, setCompare] = useState(false);
  const [previewTick, setPreviewTick] = useState(0);
  const [previewBusy, setPreviewBusy] = useState(false);
  const [previewError, setPreviewError] = useState("");
  const [limbShape, setLimbShape] = useState(null);
  const [limbBusy, setLimbBusy] = useState(false);
  const [modelReady, setModelReady] = useState(false);
  const [materializing, setMaterializing] = useState(false);
  const [dressed, setDressed] = useState(stored.dressed !== false);
  const [outfitChoice, setOutfitChoice] = useState(stored.outfitChoice || { jersey: "jersey_classic_u", shorts: "shorts_classic" });
  const [outfitCatalog, setOutfitCatalog] = useState({ jerseys: [], shorts: [], shoes: [], hair: [], uniforms: [], ready: false });
  const [outfitError, setOutfitError] = useState("");
  const [clothesNotes, setClothesNotes] = useState([]);
  const activeRef = useRef(true);
  const profileSeeded = useRef(Boolean(stored.profile));
  const evidenceRef = useRef(null);
  const draftRef = useRef(plan);
  const activityRef = useRef(false);
  activityRef.current = busy || previewBusy || Boolean(reference?.busy);
  draftRef.current = plan;
  const player = (players || []).find((entry) => (entry.playerId || entry.id) === playerId);
  const name = playerNameFromLabel(player?.name || player?.label || playerId);
  searchTargetRef.current = photoTargetKey({ playerId, name, season, team });
  const query = new URLSearchParams({ playerId: playerId || "", ...(modsRoot ? { modsRoot } : {}) }).toString();
  const evidenceReady = Boolean(reference?.result?.profile && hasUsableReferenceMeasurements(reference.result.profile) && reference.result.profile.overallReadiness !== "needs_more_images" && reference.images?.length && !reference.busy);
  const currentBody = appearance?.bodyFit || {};
  const selectedImage = reference?.images?.find((image) => image.id === reference.activeId) || reference?.images?.[0];
  const refresh = useCallback(async () => {
    if (!playerId) return;
    try {
      const nextStatus = await requestJson(`/api/autofit/status?${query}`);
      const nextComparison = nextStatus.packageReady ? await requestJson(`/api/autofit/comparison?${query}`) : null;
      const nextAppearance = nextStatus.packageReady ? await requestJson(`/api/appearance?${query}`) : null;
      if (!activeRef.current) return;
      setStatus(nextStatus); setComparison(nextComparison); setAppearance(nextAppearance);
      if (!profileSeeded.current && nextStatus.profile) { profileSeeded.current = true; setProfile(nextStatus.profile); }
    } catch (err) { if (activeRef.current) setError(err.message); }
  }, [playerId, query]);
  useEffect(() => { activeRef.current = true; refresh(); return () => { activeRef.current = false; }; }, [refresh]);
  // 路线 A 档案回填（2026-10-16）：草稿没存过赛季/球队时，从该球员最近一份已确认参考
  // 档案带出目标赛季+球队；档案也没有则赛季默认当前赛季。只补空，绝不覆盖用户已选值。
  useEffect(() => {
    if (!playerId) return;
    let cancelled = false;
    const fill = (entry) => {
      setSeason((current) => current || entry?.season || SEASONS[0].value);
      setTeam((current) => current || entry?.team || "");
    };
    requestJson("/api/body-reference/profiles").then((data) => {
      if (cancelled) return;
      const normalized = String(name || "").trim().toLowerCase();
      const mine = (data.profiles || []).filter((entry) => entry.playerId === playerId || (normalized && String(entry.name || "").trim().toLowerCase() === normalized));
      fill(mine[0]);
    }).catch(() => { if (!cancelled) fill(null); });
    return () => { cancelled = true; };
  }, [playerId, name]);
  // 生涯数据（2026-10-16 用户拍板）：赛季/球队选项收窄为该球员真实生涯（科比＝1996-97 到
  // 2015-16、只有湖人）。AI 未配置或查询失败时保持全量列表，安静降级。自动填过的值允许被
  // 生涯数据纠正（如默认 2026-27 → 生涯最后赛季），用户亲手选过的绝不动。
  useEffect(() => {
    if (!playerId || !name) return;
    let cancelled = false;
    requestJson(`/api/autofit/career?playerId=${encodeURIComponent(playerId)}&name=${encodeURIComponent(name)}`).then((data) => {
      if (cancelled || !data?.ok) return;
      setCareer({ seasons: data.seasons || [], teamsBySeason: data.teamsBySeason || {}, teams: data.teams || [] });
    }).catch(() => {});
    return () => { cancelled = true; };
  }, [playerId, name]);
  useEffect(() => {
    if (userSeasonRef.current || !career?.seasons?.length) return;
    setSeason((current) => (career.seasons.includes(current) ? current : career.seasons[0]));
  }, [career]);
  useEffect(() => {
    if (userTeamRef.current || !season) return;
    const forSeason = career?.teamsBySeason?.[season];
    if (forSeason?.length === 1) setTeam((current) => current || forSeason[0]);
  }, [season, career]);
  useEffect(() => {
    try { localStorage.setItem(storageKey, JSON.stringify({ team, season, step, profile, plan, writeResult, accepted, dressed, outfitChoice })); setStorageError(""); }
    catch { setStorageError("草稿未能保存，请勿关闭页面，释放存储空间后重试。"); }
  }, [storageKey, team, season, step, profile, plan, writeResult, accepted, dressed, outfitChoice]);
  useEffect(() => { onCompareApi?.({ isDirty: () => Boolean(draftRef.current), isBusy: () => activityRef.current, block: () => setError("当前步骤仍在处理中，请完成后再切换球员或工作区。") }); return () => onCompareApi?.(null); }, [onCompareApi]);
  // 与外观编辑共用预览通道。队列串行处理，清理不会越过尚在运行的设置请求。
  const previewQueue = useRef(Promise.resolve());
  useEffect(() => {
    const payload = step === 2 && plan && !compare ? plan.solution.target : null;
    let cancelled = false;
    setPreviewBusy(Boolean(payload));
    const timer = setTimeout(() => {
      previewQueue.current = previewQueue.current.catch(() => {}).then(() => post("/api/viewport/preview-morphs", { playerId, ...(modsRoot ? { modsRoot } : {}), bodyFit: payload }));
      previewQueue.current.then(() => { if (!cancelled && activeRef.current) { setModelReady(false); setPreviewTick((value) => value + 1); setPreviewError(""); setPreviewBusy(false); } })
        .catch((err) => { if (!cancelled && activeRef.current) { setPreviewError(`预览失败：${err.message}`); setPreviewBusy(false); } });
    }, 350);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [playerId, modsRoot, step, plan, compare]);
  useEffect(() => () => { previewQueue.current = previewQueue.current.catch(() => {}).then(() => post("/api/viewport/preview-morphs", { playerId, ...(modsRoot ? { modsRoot } : {}), bodyFit: null })).catch(() => {}); }, [playerId, modsRoot]);
  useEffect(() => {
    let cancelled = false;
    setOutfitCatalog({ jerseys: [], shorts: [], shoes: [], hair: [], uniforms: [], ready: false });
    setOutfitError("");
    Promise.all([
      requestJson(`/api/jersey-fit?${query}`),
      requestJson(`/api/outfit/catalog?${query}`),
      requestJson(`/api/uniform/catalog?${query}`).catch(() => ({ uniforms: [] })),
      requestJson(`/api/alignment?${query}`).catch(() => ({ targets: [] })),
    ]).then(([jerseys, catalog, uniformList, alignment]) => {
      if (cancelled) return;
      setOutfitCatalog({
        jerseys: (jerseys.variants || []).map((item) => ({ value: item.id, label: item.label })),
        shorts: (catalog.shorts || []).map((item) => ({ value: item.id, label: item.label })),
        shoes: catalog.shoeModels || [],
        hair: (alignment.targets || []).filter((item) => /hair/i.test(item.file) && !/beard|brow|facial/i.test(item.file) && item.status === "ok").map((item) => ({ value: item.file, label: item.label || item.file })),
        uniforms: (uniformList.uniforms || []).map((item) => ({ value: item.id, label: item.label })),
        ready: true,
      });
    }).catch((err) => { if (!cancelled) setOutfitError(`着装目录读取失败：${err.message}；可切换「体型」查看模型。`); });
    return () => { cancelled = true; };
  }, [query]);
  // 生涯联动选项：赛季＝他打过的赛季；球队＝当季球队（有转会计时多支），未选赛季给生涯全部队。
  const seasonOptions = useMemo(() => (career?.seasons?.length ? career.seasons.map((value) => ({ value, label: value })) : SEASONS), [career]);
  const teamOptions = useMemo(() => {
    const forSeason = season && career?.teamsBySeason?.[season];
    const list = forSeason?.length ? forSeason : career?.teams?.length ? career.teams : null;
    return list ? list.map((value) => ({ value, label: value })) : TEAMS;
  }, [career, season]);
  const shoeOptions = useMemo(() => {
    const names = new Map(SHOES.filter((item) => item.slug).map((item) => [item.slug, `${item.brandZh || item.brandName} ${item.name}`]));
    return [{ value: "", label: "不显示球鞋" }, ...outfitCatalog.shoes.map((value) => ({ value, label: names.get(value) || value }))];
  }, [outfitCatalog.shoes]);
  const selectedOutfit = useMemo(() => {
    if (!dressed || !outfitCatalog.ready) return null;
    const jersey = outfitCatalog.jerseys.some((item) => item.value === outfitChoice.jersey) ? outfitChoice.jersey : outfitCatalog.jerseys[0]?.value;
    const shorts = outfitCatalog.shorts.some((item) => item.value === outfitChoice.shorts) ? outfitChoice.shorts : outfitCatalog.shorts[0]?.value;
    const shoes = outfitChoice.shoes === "" ? "" : outfitCatalog.shoes.includes(outfitChoice.shoes) ? outfitChoice.shoes : outfitCatalog.shoes[0];
    const hair = outfitChoice.hair === "" ? "" : outfitCatalog.hair.some((item) => item.value === outfitChoice.hair) ? outfitChoice.hair : outfitCatalog.hair[0]?.value;
    // 队服（2026-10-28）：默认不穿（""），选过的 id 不在目录里（目录刷新失败/包被删）回落不穿。
    const uniform = outfitChoice.uniform && outfitCatalog.uniforms.some((item) => item.value === outfitChoice.uniform) ? outfitChoice.uniform : "";
    return { ...(jersey ? { jersey: { variant: jersey } } : {}), ...(shorts ? { shorts } : {}), ...(shoes ? { shoes } : {}), ...(hair ? { hair } : {}), ...(uniform ? { uniform } : {}) };
  }, [dressed, outfitCatalog, outfitChoice]);
  const outfitKey = JSON.stringify(selectedOutfit);
  useEffect(() => { setModelReady(false); setPreviewError(""); setClothesNotes([]); }, [outfitKey]);
  const changeOutfit = (key, value) => setOutfitChoice((previous) => ({ ...previous, [key]: value }));
  const changeDisplay = (value) => setDressed(value);
  const invalidate = () => { setPlan(null); setChecking(false); setAccepted(false); setWriteResult(null); };
  const receiveReference = useCallback((next) => {
    if (next.migratedSearch && !next.result) { setPlan(null); setChecking(false); setAccepted(false); setWriteResult(null); setStep(0); }
    const signature = JSON.stringify([next.season, next.images.map((image) => [image.id, image.annotation, image.tier, image.claimedSeason, image.source])]);
    if (evidenceRef.current !== null && evidenceRef.current !== signature) { setPlan(null); setChecking(false); setAccepted(false); setWriteResult(null); }
    evidenceRef.current = signature; setReference(next);
  }, []);
  const changeProfile = (patch) => { setProfile((value) => ({ ...value, ...patch })); invalidate(); };
  const run = async (operation) => {
    setBusy(true); setError("");
    try { await operation(); } catch (err) { if (activeRef.current) setError(err.message); }
    finally { if (activeRef.current) setBusy(false); }
  };
  const findPhotos = () => run(async () => {
    if (!season.trim() || !team.trim()) throw new Error("请填写目标赛季和目标球队后搜索照片。");
    const target = { playerId, name, season, team };
    const targetKey = photoTargetKey(target);
    const requestId = ++searchRequestRef.current;
    setImportedImages(null); setResearch(null);
    const dossier = await post("/api/autofit/research", target);
    if (!activeRef.current || requestId !== searchRequestRef.current || targetKey !== searchTargetRef.current) return;
    setResearch(dossier);
    if (dossier.images?.length) {
      // 候选与逐图筛选记录按来源配对（accepted 与待核对都进确认列表；待核对项由
      // 确认按钮标记 identityConfirmation 后以 manual 身份入参考——16c7062 确认流）。
      const rows = (dossier.photoReview || []).filter((item) => item.status !== "rejected");
      const matched = dossier.images.map((url, index) => {
        const source = dossier.imageSources?.[index];
        const row = rows.find((item) => item.source === source) || null;
        return row && { url, source, screening: { version: PHOTO_SCREENING_VERSION, status: row.status, name, season, team, checkedAt: new Date().toISOString() } };
      });
      if (matched.some((item) => !item)) throw new Error("搜索结果缺少逐图筛选记录，未自动导入；请重新打开 Mod Work 后重试。");
      setImportedImages(matched);
    }
    if (dossier.measurements) changeProfile({ heightCm: dossier.measurements.heightCm || profile.heightCm, weightKg: dossier.measurements.weightKg || profile.weightKg });
    if (dossier.ok && !dossier.images?.length && dossier.photoReview?.length) return;
    if (!dossier.ok || !dossier.images?.length) throw new Error(dossier.error || (dossier.photoReview?.length ? "没有通过筛选的照片。展开「搜索筛选结果」查看原因，或手动添加并核对照片。" : "未找到可用照片。请添加真实全身照并核对来源和赛季。"));
  });
  const solve = () => run(async () => {
    if (!evidenceReady) throw new Error("请先分析并核对参考照片。");
    if (!status?.packageReady) { setMaterializing(true); return; }
    const confirmedProfile = { ...profile, name, sources: [`参考：${reference.result.savedAs || "本次照片分析"} · ${season}`, ...(research?.snippets || []).map((item) => item.url).filter(Boolean)] };
    // v0.2（2026-10-15 用户拍板）：参考分析的融合比例量测随画像进求解，服务端直读包网格
    // 算游戏基线做比例差调制（±6% 容差带、保守限幅、肢段目标+缩头建议）。
    const measurements = reference?.result?.profile?.measurements || null;
    const next = await post("/api/autofit/solve", { playerId, modsRoot, profile: confirmedProfile, ...(measurements ? { proportions: measurements } : {}) });
    if (!activeRef.current) return;
    // 肢段目标灌进既有「臂腿形状」编辑区（左右对称、可改可放弃；预览/写入仍走原按钮，零新写入路径）。
    if (next.solution?.limbTargets) {
      for (const [segment, fields] of Object.entries(next.solution.limbTargets)) {
        const group = segment.replace(/^[LR]/, "");
        for (const [field, value] of Object.entries(fields)) editLimb(group, field, value);
      }
    }
    await post("/api/autofit/profile", { playerId, profile: confirmedProfile });
    if (!activeRef.current) return;
    const latest = await requestJson(`/api/appearance?${query}`);
    if (!activeRef.current) return;
    if (!sameBody(next.baseline, latest.bodyFit)) throw new Error("求解期间球员文件发生变化，请重新生成方案。");
    setPlan({ ...next, baseline: next.baseline, evidence: evidenceRef.current }); setStep(2); setChecking(false); setCompare(false); setWriteResult(null);
  });
  const preparePackage = () => run(async () => { await post("/api/players/materialize-stock", { playerId, modsRoot }); if (activeRef.current) { setMaterializing(false); await refresh(); } });
  // 画像 AI 建议（2026-10-15 leverage llm）：量测+调研摘要 → 起草体型/强调填进选择器，人可改。
  const [suggestBusy, setSuggestBusy] = useState(false);
  const [suggestNote, setSuggestNote] = useState("");
  const suggestProfile = async () => {
    if (suggestBusy) return;
    setSuggestBusy(true);
    setSuggestNote("");
    try {
      const measurements = reference?.result?.profile?.measurements || null;
      const result = await post("/api/autofit/suggest-profile", {
        name, season,
        heightCm: Number(profile.heightCm) || null,
        weightKg: Number(profile.weightKg) || null,
        ...(measurements ? { measurements } : {}),
        snippets: research?.snippets || [],
      });
      const suggestion = result.suggestion || {};
      const next = { ...profile };
      if (suggestion.buildType) next.buildType = suggestion.buildType;
      if (suggestion.emphasis && Object.keys(suggestion.emphasis).length) next.emphasis = { ...(profile.emphasis || {}), ...suggestion.emphasis };
      setProfile(next);
      setSuggestNote(`AI 建议${result.rationale ? "：" + result.rationale : "已填入"}——只是起草，可改。`);
    } catch (error) {
      setSuggestNote(`AI 建议失败：${error?.message || "未知原因"}；手动选择不受影响。`);
    } finally {
      setSuggestBusy(false);
    }
  };
  const editChannel = (key, value) => { setPlan((previous) => ({ ...previous, solution: { ...previous.solution, target: { ...previous.solution.target, [key]: Math.round(Math.max(BODY_FIT_MIN, Math.min(BODY_FIT_MAX, value)) * 100) / 100 } } })); setChecking(false); setCompare(false); };
