            {BODY_PARTS.filter((part) => part.region === region && plan).map((part) => {
              const target = plan.solution.target; const thick = target[`${part.key}THICK`] ?? currentBody[`${part.key}THICK`] ?? 0; const thin = target[`${part.key}THIN`] ?? currentBody[`${part.key}THIN`] ?? 0; const merged = mergedBodyFitValue(thick, thin);
              return <section className="apx-part" key={part.key}><h4>{part.label}</h4>{merged == null ? ["THICK", "THIN"].map((suffix) => <label className="settings-row inline" key={suffix}>{suffix === "THICK" ? "粗壮" : "纤瘦"}<NumericInput className="num-input" ariaLabel={`${part.label}${suffix}`} value={target[`${part.key}${suffix}`] ?? currentBody[`${part.key}${suffix}`] ?? 0} format={numeric} commit={(value) => editChannel(`${part.key}${suffix}`, value)} step={0.01} /></label>) : <><NumericInput className="num-input" ariaLabel={`${part.label}体型数值`} value={merged} format={numeric} commit={(value) => editPart(part, value)} step={0.01} /><ScaleRange value={merged} min={BODY_FIT_MIN} max={BODY_FIT_MAX} step={0.01} tickStep={0.1} ariaLabel={`${part.label}体型`} startLabel="纤瘦" endLabel="粗壮" onChange={(value) => editPart(part, value)} /></>}</section>;
            })}{region === "limbs" ? <section className="apx-part"><h4>臂腿形状雕刻</h4>
              <p className="autofit-evidence-note">左右对称生效；「预览形状」立即在模型上显示（不写盘），确认后「写入形状」才落包。形状与粗细通道叠加。</p>
              {limbShape ? LIMB_GROUPS.map(([group, label]) => <section key={group} className="apx-part"><h5>{label}</h5>
                {LIMB_FIELDS.map((field) => {
                  const current = limbShape["L" + group]?.[field.key] ?? limbShape["R" + group]?.[field.key] ?? 0;
                  const numeric = (value) => (field.key === "scale" ? "×" : (value > 0 ? "+" : "")) + Number(value).toFixed(2);
                  return <label className="settings-row inline" key={field.key}>{field.label}<NumericInput className="num-input" ariaLabel={label + field.label} value={current} format={numeric} commit={(value) => editLimb(group, field.key, value)} step={field.step} /><ScaleRange value={current} min={field.min} max={field.max} step={field.step} tickStep={0.05} ariaLabel={label + field.label + "滑杆"} startLabel={field.key === "scale" ? "细" : "−"} endLabel={field.key === "scale" ? "粗" : "+"} onChange={(value) => editLimb(group, field.key, value)} /></label>;
                })}
              </section>) : <p className="autofit-empty">肢段参数读取中…</p>}
              <div className="autofit-plan-actions"><button type="button" className="ghost-action" disabled={limbBusy || !limbShape} onClick={previewLimbs}>预览形状</button><button type="button" className="primary-action" disabled={limbBusy || !limbShape} onClick={applyLimbs}>{limbBusy ? "写入中…" : "写入形状"}</button></div>
              {limbBusy ? <span className="autofit-model-status" role="status">正在写入肢段…</span> : null}
            </section> : null}</details><p className="autofit-preview-note"><Info size="1rem" weight="fill" aria-hidden="true" /><span>胸部等变化需游戏内确认。建议来自画像与方案参数，照片比例尚未直接转换为游戏参数。</span></p>
          </>}
        </> : <><h4>{accepted ? "游戏内已确认" : "已写入，待游戏内确认"}</h4><p className="autofit-evidence-note">本次 {writeResult?.channels || 0} 个通道。查看游戏里的实际效果后再完成验收。</p><DataTable ariaLabel="本次写入对比" columns={WRITE_COLUMNS} rows={writtenRows} rowKey="key" /><button type="button" className="ghost-action" onClick={() => { setAccepted(false); setStep(1); }}>继续调整</button>
          {writeResult?.backupDir ? <p className="autofit-evidence-note">备份位置：{writeResult.backupDir}</p> : null}
          {writeResult?.warnings?.length ? <p className="autofit-error" role="alert">{writeResult.warnings.join("；")}</p> : null}
          <details><summary>当前与原版基准</summary><DataTable ariaLabel="当前与原版" columns={[{ key: "label", title: "部位" }, { key: "original", title: "基准", render: (row) => numeric(row.original) }, { key: "current", title: "当前", render: (row) => numeric(row.current) }]} rows={(comparison?.groups || []).flatMap((group) => group.channels)} rowKey="key" /></details>
        </>}
        </fieldset>
      </aside>
    </div> : null}
    <footer className="autofit-footer">{storageError || reference?.persisted === false ? "草稿未完整保存，请勿关闭页面" : reference?.busy ? "正在保存参考…" : "草稿已保存"} · {accepted ? "游戏内已确认" : writeResult ? "已写入，待游戏内确认" : plan ? "方案未写入游戏" : "仅研究参考，不改游戏"}</footer>
  </div></div>;
}

// 服装版型工作区（2026-09-22 合并）：球衣版型 + 球裤宽松度收进一个侧栏入口。
// 「球衣 / 球裤 / 全身」是右侧参数栏的二级标题栏。球衣和球裤各自写入；全身只把两页
// 当前的款式和滑杆穿在一起看，不另存一套，也不写入。两页保持挂载，切走再回来尺寸还在。
// 2026-10-25 全身页打磨：就绪清单、分件摘要卡、跳转球衣/球裤、空态与 a11y 对齐查询页签。
import { useEffect, useId, useMemo, useState } from "react";
import { CheckCircle, CircleDashed, TShirt, WarningCircle } from "@phosphor-icons/react";
import { useUiT } from "./ui-i18n.js";
import { WorkspaceHeader } from "./WorkspaceHeader.jsx";
import { FitViewport } from "./FitViewport.jsx";
import { JerseyFitWorkspace } from "./JerseyFit.jsx";
import { ShortsLoosenWorkspace } from "./ShortsLoosen.jsx";
import { jerseyFitPositions } from "../shared/jersey-fit-core.mjs";
import { loosenPositions } from "../shared/shorts-loosen-core.mjs";
import { tabListKeyDown } from "./roving.js";

export const CLOTHING_TAB_STORAGE_KEY = "fit-studio.clothing.tab";

const CLOTHING_TABS = [
  { id: "jersey", nameKey: "page.clothing.jersey" },
  { id: "shorts", nameKey: "page.clothing.shorts" },
  { id: "body", nameKey: "page.clothing.body" },
];

function readStoredClothingTab() {
  try {
    const stored = window.localStorage.getItem(CLOTHING_TAB_STORAGE_KEY);
    if (stored === "shorts" || stored === "body") return stored;
  } catch { /* 无本地存储时回默认页签 */ }
  return "jersey";
}

function PieceCard({ ready, title, label, summary, unit, onEdit, editLabel }) {
  return (
    <article className={`clothing-body-card${ready ? " is-ready" : " is-pending"}`}>
      <header className="clothing-body-card-head">
        <span className="clothing-body-card-status" aria-hidden="true">
          {ready
            ? <CheckCircle size="1rem" weight="fill" />
            : <CircleDashed size="1rem" />}
        </span>
        <div className="clothing-body-card-titles">
          <h4>{title}</h4>
          <p>{ready ? (label || "已载入") : "尚未从对应页读到尺寸"}</p>
        </div>
      </header>
      {ready && summary ? (
        <p className="clothing-body-card-summary" title={summary}>
          {summary}{unit || ""}
        </p>
      ) : (
        <p className="clothing-body-card-summary is-empty">
          切到「{title}」页调好尺寸，再回来一起看。
        </p>
      )}
      <button type="button" className="ghost-action clothing-body-card-action" onClick={onEdit}>
        {editLabel}
      </button>
    </article>
  );
}

function FullOutfitWorkspace({
  mode,
  theme,
  jersey,
  shorts,
  showUnderwear,
  onShowUnderwearChange,
  onOpenTab,
}) {
  const [bodyMode, setBodyMode] = useState("solid");
  const [cameraView, setCameraView] = useState("front");
  const [meshInfo, setMeshInfo] = useState(null);
  const playerId = jersey?.playerId || shorts?.playerId || "";
  const jerseyReady = Boolean(jersey?.variant);
  const shortsReady = Boolean(shorts?.variant);
  const outfit = useMemo(() => {
    if (!playerId || !jersey?.variant) return null;
    const value = { jersey: { variant: jersey.variant } };
    if (shorts?.variant) {
      value.shorts = shorts.variant;
      value.shortsLive = true;
    }
    if (jersey.shoeModel) value.shoes = jersey.shoeModel;
    if (jersey.hairFile && playerId) value.hair = jersey.hairFile;
    return value;
  }, [playerId, jersey, shorts]);
  const clothDeform = useMemo(() => [
    jersey?.params ? {
      pieceId: "jersey",
      params: jersey.params,
      fn: (positions, next, bands) => jerseyFitPositions(positions, next, bands),
    } : null,
    shorts?.params ? {
      pieceId: "shorts",
      params: shorts.params,
      fn: (positions, next, bands) => loosenPositions(positions, next, bands),
    } : null,
  ].filter(Boolean), [jersey?.params, shorts?.params]);

  const accessories = [
    jersey?.shoeModel ? { key: "shoes", label: "球鞋", value: jersey.shoeModel } : null,
    jersey?.hairFile ? { key: "hair", label: "发型", value: jersey.hairFile } : null,
  ].filter(Boolean);

  const previewEmpty = !playerId
    ? {
      title: "先在页头选好球员",
      detail: "选中已导入球员包的球员后，这里会叠上全身预览。球衣与球裤尺寸仍从对应页读取。",
    }
    : !jerseyReady
      ? {
        title: "还缺球衣尺寸",
        detail: "全身预览以球衣页当前款式为底。先到「球衣」页读出款式，再回来看整套。",
        action: { label: "去球衣页", tab: "jersey" },
      }
      : null;

  const preview = (
    <section className="shorts-loosen-stage" aria-label="全身上身预览">
      {playerId && jerseyReady ? (
        <div className="jersey-outfit-viewport mesh-viewport">
          <FitViewport
            part="full"
            playerId={playerId}
            theme={theme}
            bodyMode={bodyMode}
            viewMode={cameraView}
            onViewModeChange={setCameraView}
            outfit={outfit}
            clothDeform={clothDeform}
            clothFlutter={jersey?.flutter ?? 40}
            showUnderwear={showUnderwear}
            showRuler={false}
            onMeshInfo={setMeshInfo}
          />
          <div className="jersey-vpdock is-start">
            <div className="view-angle-switch" role="group" aria-label="身体显示">
              <button type="button" className={bodyMode === "solid" ? "active" : ""} aria-pressed={bodyMode === "solid"} onClick={() => setBodyMode("solid")}>实体</button>
              <button type="button" className={bodyMode === "xray" ? "active" : ""} aria-pressed={bodyMode === "xray"} data-tip="衣服变透，能看出和身体的距离" onClick={() => setBodyMode("xray")}>X 光</button>
            </div>
          </div>
          <div className="jersey-vpdock">
            <div className="view-angle-switch" role="group" aria-label="观察视图">
              <button type="button" className={cameraView === "front" ? "active" : ""} aria-pressed={cameraView === "front"} onClick={() => setCameraView("front")}>正面</button>
              <button type="button" className={cameraView === "left" ? "active" : ""} aria-pressed={cameraView === "left"} onClick={() => setCameraView("left")}>左侧</button>
              <button type="button" className={cameraView === "right" ? "active" : ""} aria-pressed={cameraView === "right"} onClick={() => setCameraView("right")}>右侧</button>
              <button type="button" className={cameraView === "back" ? "active" : ""} aria-pressed={cameraView === "back"} onClick={() => setCameraView("back")}>背面</button>
            </div>
            <div className="view-angle-switch" role="group" aria-label="内衣模型">
              <button type="button" className={showUnderwear ? "active" : ""} aria-pressed={showUnderwear} data-tip="球裤里面的内裤。只影响预览，不写入游戏。" onClick={() => onShowUnderwearChange?.(!showUnderwear)}>内衣</button>
            </div>
          </div>
        </div>
      ) : (
        <div className="shorts-preview jersey-player-empty clothing-body-empty" role="status">
          <TShirt size="1.75rem" aria-hidden="true" />
          <strong>{previewEmpty?.title}</strong>
          <span className="shorts-loosen-hint">{previewEmpty?.detail}</span>
          {previewEmpty?.action ? (
            <button type="button" className="ghost-action" onClick={() => onOpenTab?.(previewEmpty.action.tab)}>
              {previewEmpty.action.label}
            </button>
          ) : null}
        </div>
      )}
      {meshInfo?.error ? <p className="shorts-loosen-job error" role="alert">{meshInfo.error}</p> : null}
    </section>
  );
  if (mode === "preview") return preview;

  const bothReady = jerseyReady && shortsReady;
  const readinessLabel = !jerseyReady && !shortsReady
    ? "两边都还没读到尺寸"
    : !jerseyReady
      ? "还缺球衣"
      : !shortsReady
        ? "还缺球裤（可先只看球衣）"
        : "球衣与球裤都已就绪";

  return (
    <div className="clothing-fit-split">
      <div className="shorts-loosen-body">
        <section className="shorts-loosen-panel clothing-body-panel" aria-label="全身当前尺寸">
          <div className="clothing-body-intro">
            <p className="clothing-body-lead">
              把球衣页和球裤页上<strong>当前</strong>的款式与尺寸叠在一起看。改尺寸请回到对应页；这里不另写一套，也不写入游戏。
            </p>
            <p className={`clothing-body-readiness${bothReady ? " is-ready" : " is-pending"}`} role="status">
              {bothReady
                ? <CheckCircle size="0.9375rem" weight="fill" aria-hidden="true" />
                : <WarningCircle size="0.9375rem" weight="fill" aria-hidden="true" />}
              <span>{readinessLabel}</span>
            </p>
          </div>

          <div className="clothing-body-cards">
            <PieceCard
              ready={jerseyReady}
              title="球衣"
              label={jersey?.label}
              summary={jersey?.summary}
              onEdit={() => onOpenTab?.("jersey")}
              editLabel={jerseyReady ? "去球衣页调整" : "去球衣页读取"}
            />
            <PieceCard
              ready={shortsReady}
              title="球裤"
              label={shorts?.label}
              summary={shorts?.summary}
              unit={shorts?.summary ? " mm" : ""}
              onEdit={() => onOpenTab?.("shorts")}
              editLabel={shortsReady ? "去球裤页调整" : "去球裤页读取"}
            />
          </div>

          {accessories.length ? (
            <div className="clothing-body-accessories" aria-label="预览搭配">
              <h4>预览搭配</h4>
              <ul>
                {accessories.map((item) => (
                  <li key={item.key}>
                    <span>{item.label}</span>
                    <strong title={item.value}>{item.value}</strong>
                  </li>
                ))}
              </ul>
              <p className="shorts-loosen-hint">球鞋与发型来自球衣页的预览选项，只影响左侧视口。</p>
            </div>
          ) : jerseyReady ? (
            <p className="shorts-loosen-hint clothing-body-accessories-empty">
              球衣页可另选预览球鞋与发型；未选时全身只看球衣与球裤。
            </p>
          ) : null}

          <details className="shorts-loosen-principle clothing-body-principle">
            <summary>这一页做什么</summary>
            <p>全身是对照台，不是第三套写入入口。写入球衣或球裤请在对应页确认；恢复官方也在对应页操作。布料宽松也在球衣页和球裤页，跟毫米版型分开写。</p>
          </details>
        </section>
      </div>
    </div>
  );
}

export function ClothingFitWorkspace({ theme = "dark", playerId = "", players = [], gameRunning = false }) {
  const t = useUiT();
  const tabsId = useId();
  const [tab, setTab] = useState(readStoredClothingTab);
  const [actionsHost, setActionsHost] = useState(null);
  const [previewHost, setPreviewHost] = useState(null);
  const [showUnderwear, setShowUnderwear] = useState(true);
  const [jerseyLive, setJerseyLive] = useState(null);
  const [shortsLive, setShortsLive] = useState(null);
  useEffect(() => {
    try { window.localStorage.setItem(CLOTHING_TAB_STORAGE_KEY, tab); } catch { /* 忽略隐私模式写入失败 */ }
  }, [tab]);

  function chooseTab(next) {
    setTab(next);
  }

  const tabSwitch = (
    <div
      className="clothing-tab-switch"
      role="tablist"
      aria-label={t("ws.clothing")}
      onKeyDown={(event) => tabListKeyDown(event, CLOTHING_TABS.map((item) => item.id), tab, chooseTab)}
    >
      {CLOTHING_TABS.map(({ id, nameKey }) => (
        <button
          key={id}
          type="button"
          role="tab"
          id={`${tabsId}-tab-${id}`}
          aria-controls={`${tabsId}-panel-${id}`}
          aria-selected={tab === id}
          tabIndex={tab === id ? 0 : -1}
          className={tab === id ? "active" : ""}
          onClick={() => chooseTab(id)}
        >
          {t(nameKey)}
        </button>
      ))}
    </div>
  );

  return (
    <div className="shoe-workspace clothing-workspace">
      <div className="clothing-workspace-head panel-surface">
        {/* 球员选择不在本页页头重复（2026-10-09 用户「统一成全局一个球员选择器」）：
            标题栏的「当前球员」select（App title-player-select）是唯一入口，全局换人后
            球衣/球裤/全身三页的预览身体跟着换；本页只消费 playerId/players。 */}
        <WorkspaceHeader title={t("ws.clothing")}>
          <span className="fit-head-actions" ref={setActionsHost} />
        </WorkspaceHeader>
      </div>
      <div className="clothing-workspace-body">
        <section className="clothing-preview-pane" ref={setPreviewHost} aria-label="建模预览">
          {tab === "body" ? (
            <FullOutfitWorkspace
              mode="preview"
              theme={theme}
              jersey={jerseyLive}
              shorts={shortsLive}
              showUnderwear={showUnderwear}
              onShowUnderwearChange={setShowUnderwear}
              onOpenTab={chooseTab}
            />
          ) : null}
        </section>
        <div className="clothing-editor panel-surface">
          <div className="section-heading">{tabSwitch}</div>
          <div
            className="clothing-tab-pane"
            role="tabpanel"
            id={`${tabsId}-panel-jersey`}
            aria-labelledby={`${tabsId}-tab-jersey`}
            hidden={tab !== "jersey"}
          >
            <JerseyFitWorkspace
              theme={theme}
              embedded
              playerId={playerId}
              players={players}
              gameRunning={gameRunning}
              actionsHost={tab === "jersey" ? actionsHost : null}
              previewHost={tab === "jersey" ? previewHost : null}
              showUnderwear={showUnderwear}
              onShowUnderwearChange={setShowUnderwear}
              onLiveChange={setJerseyLive}
            />
          </div>
          <div
            className="clothing-tab-pane"
            role="tabpanel"
            id={`${tabsId}-panel-shorts`}
            aria-labelledby={`${tabsId}-tab-shorts`}
            hidden={tab !== "shorts"}
          >
            <ShortsLoosenWorkspace
              theme={theme}
              embedded
              playerId={playerId}
              players={players}
              gameRunning={gameRunning}
              actionsHost={tab === "shorts" ? actionsHost : null}
              previewHost={tab === "shorts" ? previewHost : null}
              showUnderwear={showUnderwear}
              onShowUnderwearChange={setShowUnderwear}
              onLiveChange={setShortsLive}
            />
          </div>
          <div
            className="clothing-tab-pane"
            role="tabpanel"
            id={`${tabsId}-panel-body`}
            aria-labelledby={`${tabsId}-tab-body`}
            hidden={tab !== "body"}
          >
            <FullOutfitWorkspace
              mode="editor"
              theme={theme}
              jersey={jerseyLive}
              shorts={shortsLive}
              showUnderwear={showUnderwear}
              onShowUnderwearChange={setShowUnderwear}
              onOpenTab={chooseTab}
            />
          </div>
        </div>
      </div>
    </div>
  );
}
